import{_ as e,o as i,c as a,ag as r}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"Civilization-related JSON files","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/Mod-file-structure/2-Civilization-related-JSON-files.md","filePath":"Modders/Mod-file-structure/2-Civilization-related-JSON-files.md"}'),d={name:"Modders/Mod-file-structure/2-Civilization-related-JSON-files.md"};function s(n,t,o,l,h,c){return i(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="civilization-related-json-files" tabindex="-1">Civilization-related JSON files <a class="header-anchor" href="#civilization-related-json-files" aria-label="Permalink to &quot;Civilization-related JSON files&quot;">​</a></h1><h2 id="beliefs-json" tabindex="-1">Beliefs.json <a class="header-anchor" href="#beliefs-json" aria-label="Permalink to &quot;Beliefs.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Beliefs.json" target="_blank" rel="noreferrer">link to original</a></p><p>This file contains the beliefs that can be chosen for religions in your mod.</p><p>Each belief has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>type</td><td>Enum</td><td>Required</td><td>Type of belief. Value must be Pantheon, Founder, Follower or Enhancer</td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this belief adds to cities following it</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><h2 id="buildings-json" tabindex="-1">Buildings.json <a class="header-anchor" href="#buildings-json" aria-label="Permalink to &quot;Buildings.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Buildings.json" target="_blank" rel="noreferrer">link to original</a></p><p>This file contains all the buildings and wonders you want to use in your mod.</p><p>Each building has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>cost</td><td>Integer</td><td>-1</td><td>Amount of production required to build the building. If -1, the <code>buildingCost</code> from <code>requiredTech</code> <a href="#column-structure">column</a> is used</td></tr><tr><td><a href="./3-Map-related-JSON-files.html#general-stat"><code>&lt;stats&gt;</code></a></td><td>Float</td><td>0</td><td>Per-turn yield produced by the building</td></tr><tr><td>maintenance</td><td>Integer</td><td>0</td><td>Maintenance cost of the building</td></tr><tr><td>isWonder</td><td>Boolean</td><td>false</td><td>Whether this building is a global wonder</td></tr><tr><td>isNationalWonder</td><td>Boolean</td><td>false</td><td>Whether this building is a national wonder</td></tr><tr><td>requiredBuilding</td><td>String</td><td>none</td><td>A building that has to be built before this building can be built. Must be in <a href="#buildingsjson">Buildings.json</a></td></tr><tr><td>requiredTech</td><td>String</td><td>none</td><td>The tech that should be researched before this building may be built. Must be in <a href="#techsjson">Techs.json</a></td></tr><tr><td>requiredResource</td><td>String</td><td>none</td><td>The resource that is consumed when building this building. Must be in <a href="./3-Map-related-JSON-files.html#tileresourcesjson">TileResources.json</a></td></tr><tr><td>requiredNearbyImprovedResources</td><td>List of Strings</td><td>empty</td><td>The building can only be built if any of the resources in this list are within the borders of this city and have been improved. Each resource must be in <a href="./3-Map-related-JSON-files.html#tileresourcesjson">TileResources.json</a></td></tr><tr><td>replaces</td><td>String</td><td>none</td><td>The name of a building that should be replaced by this building. Must be in <a href="#buildingsjson">Buildings.json</a></td></tr><tr><td>uniqueTo</td><td>String</td><td>none</td><td>If supplied, only the nation with this name can build this building. Must be in <a href="#nationsjson">Nations.json</a></td></tr><tr><td>cityStrength</td><td>Integer</td><td>0</td><td>Strength bonus the city in which this building is built receives</td></tr><tr><td>cityHealth</td><td>Integer</td><td>0</td><td>Health bonus the city in which this building is built receives</td></tr><tr><td>hurryCostModifier</td><td>Integer</td><td>0</td><td>When this building is bought using gold or faith, the price is increased by this much percent</td></tr><tr><td>quote</td><td>String</td><td>none</td><td>If this building is a (national) wonder, this string will be shown on the completion popup</td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this building has</td></tr><tr><td>replacementTextForUniques</td><td>String</td><td>none</td><td>If provided, this string will be shown instead of all of the uniques</td></tr><tr><td>percentStatBonus</td><td>Object</td><td>none</td><td>Percentual bonus for stats provided by the building. Same format as <a href="./3-Map-related-JSON-files.html#specialized-stats">specialized stats</a> (numbers are in percent. i.e. <code>[30]</code> represents 30% <strong>bonus</strong> to a stat)</td></tr><tr><td>greatPersonPoints</td><td>Object</td><td>none</td><td>Great person points by this building generated per turn. Valid keys are the names of units (Great Scientist, Warrior, etc.), valid values are Integers</td></tr><tr><td>specialistSlots</td><td>Object</td><td>none</td><td>Specialist slots provided by this building. Valid keys are the names of specialists (as defined in <a href="#specialistsjson">Specialists.json</a>), valid values are Integers, the amount of slots provided for this specialist</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><h2 id="nations-json" tabindex="-1">Nations.json <a class="header-anchor" href="#nations-json" aria-label="Permalink to &quot;Nations.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Nations.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file contains all the nations and city states, including Barbarians and Spectator.</p><p>Each nation has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>leaderName</td><td>String</td><td>none</td><td>Omit only for city states! If you want LeaderPortraits, the image file names must match exactly, including case</td></tr><tr><td>style</td><td>String</td><td>none</td><td>Modifier appended to pixel unit image names</td></tr><tr><td>cityStateType</td><td>String</td><td>none</td><td>Distinguishes major civilizations from city states (must be in <a href="#citystatetypesjson">CityStateTypes.json</a>)</td></tr><tr><td>startBias</td><td>List of strings</td><td>empty</td><td>Zero or more of: <a href="./../Unique-parameters.html#terrainfilter">terrainFilter</a> or &quot;Avoid [terrainFilter]&quot;. Also merged with <code>Start bias [terrainFilter]</code> uniques on the nation and (for city-states) on their CityStateType. [^S]</td></tr><tr><td>preferredVictoryType</td><td>String</td><td>Neutral</td><td>The victory type major civilizations will pursue (need not be specified in <a href="./5-Miscellaneous-JSON-files.html#victorytypesjson">VictoryTypes.json</a>)</td></tr><tr><td>personality</td><td>String</td><td>none</td><td>The name of the personality specified in <a href="#personalitiesjson">Personalities.json</a> [^P]</td></tr><tr><td>favoredReligion</td><td>String</td><td>none</td><td>The religion major civilization will choose if available when founding a religion. Must be in <a href="#religionsjson">Religions.json</a></td></tr><tr><td>startIntroPart1</td><td>String</td><td>none</td><td>Introductory blurb shown to Player on game start... [^V]</td></tr><tr><td>startIntroPart2</td><td>String</td><td>none</td><td>... second paragraph. <em><strong>NO</strong></em> &quot;TBD&quot;!!! Leave empty to skip that alert.</td></tr><tr><td>declaringWar</td><td>String</td><td>none</td><td>Another greeting, voice hook supported [^V]</td></tr><tr><td>attacked</td><td>String</td><td>none</td><td>Another greeting, voice hook supported [^V]</td></tr><tr><td>defeated</td><td>String</td><td>none</td><td>Another greeting, voice hook supported [^V]</td></tr><tr><td>denounced</td><td>String</td><td>none</td><td>Another greeting, voice hook supported [^V]</td></tr><tr><td>neutralDenouncing</td><td>String</td><td>none</td><td>Greeting shown in popup when a civ denounces another civ, voice hook supported [^V]</td></tr><tr><td>hateDenouncing</td><td>String</td><td>none</td><td>Greeting shown in popup when an AI denounces its enemy, voice hook supported [^V]</td></tr><tr><td>introduction</td><td>String</td><td>none</td><td>Another greeting, voice hook supported [^V]</td></tr><tr><td>neutralHello</td><td>String</td><td>none</td><td>Another greeting, voice hook supported [^V]</td></tr><tr><td>hateHello</td><td>String</td><td>none</td><td>Another greeting, voice hook supported [^V]</td></tr><tr><td>tradeRequest</td><td>String</td><td>none</td><td>Another greeting, voice hook supported [^V]</td></tr><tr><td>declaringFriendship</td><td>String</td><td>none</td><td>Another greeting, voice hook supported [^V]</td></tr><tr><td>neutralRejectingDemand</td><td>String</td><td>none</td><td>Another greeting, the leader will say this after rejecting your demand, voice hook supported [^V]</td></tr><tr><td>hateRejectingDemand</td><td>String</td><td>none</td><td>Another greeting, the leader will say this after rejecting your demand, voice hook supported [^V]</td></tr><tr><td>innerColor</td><td><a href="./5-Miscellaneous-JSON-files.html#rgb-colors-list">List of 3× Integer</a></td><td>black</td><td>RGB color for outer ring of nation icon</td></tr><tr><td>outerColor</td><td><a href="./5-Miscellaneous-JSON-files.html#rgb-colors-list">List of 3× Integer</a></td><td>Required</td><td>RGB color for inner circle of nation icon</td></tr><tr><td>uniqueName</td><td>String</td><td>none</td><td>Decorative name for the special characteristic of this nation</td></tr><tr><td>uniqueText</td><td>String</td><td>none</td><td>Replacement text for &quot;uniques&quot;. If empty, uniques are listed individually</td></tr><tr><td>uniques</td><td>List</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this civilisation has</td></tr><tr><td>cities</td><td>List</td><td>empty</td><td>City names used sequentially for newly founded cities. Required for major civilizations and city states</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><p>[^S]: A &quot;Coast&quot; preference (<em>unless</em> combined with &quot;Avoid&quot;) is translated to a complex test for coastal land tiles, tiles next to Lakes, river tiles or near-river tiles, and such civs are processed first. Other startBias entries are ignored in that case. Other positive (no &quot;Avoid&quot;) startBias are processed next. Multiple positive preferences are treated equally, but get no &quot;fallback&quot;. Single positive startBias can get a &quot;fallback&quot; region if there is no (or no more) region with that primary type: any leftover region with as much of the specified terrain as possible will do. Multiple &quot;Avoid&quot; entries are treated equally (and reduce chance for success - if no region is left avoiding <em>all</em> specified types that civ gets a random one). When combining preferred terrain with &quot;Avoid&quot;, the latter takes precedence, and preferred terrain only has minor weight when choosing between regions that are not of a type to avoid. These notes are <strong>only</strong> valid when playing on generated maps, loaded maps from map editor get no &quot; regions&quot; and startBias is processed differently (but you can expect single-entry startBias to work best).</p><p>[^V]: See <a href="./../Images-and-Audio.html#supply-leader-voices">Supply Leader Voices</a></p><p>[^P]: Personalities for city-states work differently. The default chooses one randomly, but a mod can also specify one of Friendly, Neutral, Hostile or Irrational (case-sensitive).</p><h2 id="personalities-json" tabindex="-1">Personalities.json <a class="header-anchor" href="#personalities-json" aria-label="Permalink to &quot;Personalities.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Personalities.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file contains all Personalities for computer players.</p><p>Each personality has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>preferredVictoryType</td><td>String</td><td>Neutral</td><td>The victory type major civilizations will pursue (need not be specified in <a href="./5-Miscellaneous-JSON-files.html#victorytypesjson">VictoryTypes.json</a>)</td></tr><tr><td><a href="./3-Map-related-JSON-files.html#general-stat"><code>&lt;stats&gt;</code></a>, <a href="./2-Civilization-related-JSON-files.html#personality-behaviours"><code>&lt;behaviors&gt;</code></a></td><td>Float</td><td>5</td><td>Amount of focus on the stat the computer player will have. Typically ranges from 0 (no focus) to 10 (double focus)</td></tr><tr><td>priorities</td><td>Object</td><td>none</td><td>Priorities for each policy branch [^B]</td></tr><tr><td>uniques</td><td>List</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this personality has</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><p>[^B]: Similar to <a href="#branch-priorities">policy priorites</a> The &quot;priorities&quot; object defines the priority major civilizations&#39; AI give to a policy branch. The AI chooses the policy branch with the highest number for their preferred victory type. If two or more candidate branches have the same priority, the AI chooses a random branch among the candidates.</p><p>The object maps policy branches to priority values for the major civilization using the policy branches name and integers. Any branches not listed have a default value of 0</p><p>The code below is an example of a valid &quot;priorities&quot; definition.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;priorities&quot;: {</span></span>
<span class="line"><span>    &quot;Tradition&quot;: 30,</span></span>
<span class="line"><span>    &quot;Liberty&quot;: 20,</span></span>
<span class="line"><span>    &quot;Honor&quot;: 10</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="personality-behaviours" tabindex="-1">Personality Behaviours <a class="header-anchor" href="#personality-behaviours" aria-label="Permalink to &quot;Personality Behaviours&quot;">​</a></h3><p>Personality Behaviours <strong>are not fully implemented yet</strong> and their names may change. Using them before they are ready might make the mod unplayable. <em><strong>The following is WIP - read on at you own peril!</strong></em></p><p>There are 7 defining behaviours that influence an AI Civilization&#39;s behaviour. A higher value means they will behave more like the attribute.</p><ul><li>Military: Determines how much does the civilization prioritizes building a military, but not necessarily using it. A higher value means more focus on military, a lower value means it is likely more peaceful.</li><li>Agressive: Determines how the civilization uses its units while at war and which buildings they prioritise. A higher value means the civilization is more aggressive, a lower value means it is more defensive.</li><li>War: Determines how likely the civilization is to declare war. A 0 means the civ won&#39;t declare war at all.</li><li>Commerce: Determines how open the civilization is to trade, value open borders, and liberate city-states. A higher value means more trading frequency even with civilizations they don&#39;t like.</li><li>Diplomacy: Determines how likely the civilization is to declare friendship, a defensive pact, peace treaty, or other diplomatic actions.</li><li>Loyal: Determines how much the civilization values a long-lasting alliance, how willing they are to join wars with them, and how much they despise other unreliable civilizations.</li><li>Expansion: Determines how focused the civilization is on founding or capturing new cities. A lower value means they might focus on culture more.</li><li>DenounceWillingness: Determines how eager the civilization is to denounce other civs.</li></ul><h2 id="citystatetypes-json" tabindex="-1">CityStateTypes.json <a class="header-anchor" href="#citystatetypes-json" aria-label="Permalink to &quot;CityStateTypes.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/CityStateTypes.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This optional file is used for defining the types of city states. These types determine the benefits major civilizations get when they befriend or ally the city state with influence. For base ruleset Mods, if the file is ommitted or contains an empty list, <a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/CityStateTypes.json" target="_blank" rel="noreferrer">all types from the Vanilla ruleset</a> are automatically added: Cultured, Maritime, Mercantile, Militaristic, Religious.</p><p>Each city state type has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>friendBonusUniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> granted to major civilizations when friends with this city state</td></tr><tr><td>allyBonusUniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> granted to major civilizations when allied to city state</td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>Type-wide <a href="./../uniques.html">uniques</a> for every city-state of this type (e.g. <code>Start bias [Coast]</code>)</td></tr><tr><td>color</td><td><a href="./5-Miscellaneous-JSON-files.html#rgb-colors-list">List of 3× Integer</a></td><td>[255, 255, 255]</td><td>RGB color of text in civilopedia</td></tr></tbody></table><h2 id="policies-json" tabindex="-1">Policies.json <a class="header-anchor" href="#policies-json" aria-label="Permalink to &quot;Policies.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Policies.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file contains all the available social policies that can be &quot;bought&quot; with culture.</p><p>They are organized in &#39;branches&#39;, each branch has an &#39;opener&#39;, one or more &#39;member&#39; policies, and a &#39;finisher&#39;. Therefore this file is organized using two levels - branch and member policy.</p><p>The properties of the &#39;opener&#39; are defined with the branch level, while the &#39;finisher&#39; is an entry on the member level which <em>must</em> be named as <code>branch name + &quot; Complete&quot;</code>, case sensitive. For example, the finisher of a policy branch &quot;Tradition&quot; will have the name &quot;Tradition Complete&quot;.</p><h3 id="branch-structure" tabindex="-1">Branch structure <a class="header-anchor" href="#branch-structure" aria-label="Permalink to &quot;Branch structure&quot;">​</a></h3><p>Each policy branch has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>era</td><td>String</td><td>Required</td><td>Unlocking era as defined in <a href="./5-Miscellaneous-JSON-files.html#erasjson">Eras.json</a></td></tr><tr><td>priorities</td><td>Object</td><td>none</td><td>Priorities for each victory type, <a href="#branch-priorities">see here</a></td></tr><tr><td>uniques</td><td>List</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this policy branch grants upon adopting it</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr><tr><td>policies</td><td>List</td><td>empty</td><td>List of <a href="#member-policy-structure">member policies</a> and <a href="#branch-finisher-structure">branch &#39;finisher&#39;</a> - pay attention to the nesting of {} and []</td></tr></tbody></table><h4 id="member-policy-structure" tabindex="-1">Member policy structure <a class="header-anchor" href="#member-policy-structure" aria-label="Permalink to &quot;Member policy structure&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>row</td><td>Integer</td><td>Required</td><td>Placement in UI, each unit approximately half the icon size</td></tr><tr><td>column</td><td>Integer</td><td>Required</td><td>Placement in UI, each unit approximately half the icon size</td></tr><tr><td>requires</td><td>List</td><td>empty</td><td>List of prerequisite policy names</td></tr><tr><td>uniques</td><td>List</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this policy member grants upon adopting it</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><h4 id="branch-finisher-structure" tabindex="-1">Branch finisher structure <a class="header-anchor" href="#branch-finisher-structure" aria-label="Permalink to &quot;Branch finisher structure&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>uniques</td><td>List</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this finisher grants upon adopting all the policy members in the branch</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><h3 id="branch-priorities" tabindex="-1">Branch priorities <a class="header-anchor" href="#branch-priorities" aria-label="Permalink to &quot;Branch priorities&quot;">​</a></h3><p>The &quot;priorities&quot; object defines the priority major civilizations&#39; AI give to a policy branch. The AI chooses the policy branch with the highest sum of the peferred victory type listed here and the number listed in the personality&#39;s priority. If two or more candidate branches have the same priority, the AI chooses a random branch among the candidates.</p><p>The object maps victory types to priority values for the major civilization using strings and integers. If the preferred victory type is not specified, the default priority value is set to 0.</p><p>The code below is an example of a valid &quot;priorities&quot; definition.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;priorities&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Neutral&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Cultural&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Diplomatic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Domination&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Scientific&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="quests-json" tabindex="-1">Quests.json <a class="header-anchor" href="#quests-json" aria-label="Permalink to &quot;Quests.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Quests.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file contains the quests that may be given to major civilizations by city states.</p><p>Each quest has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td>Defines criteria of quest, <a href="#quest-name">see below</a></td></tr><tr><td>description</td><td>String</td><td>Required</td><td>Description of the quest shown to players. Can add extra information based on <code>name</code>, <a href="#quest-name">see below</a></td></tr><tr><td>type</td><td>Enum</td><td>Individual</td><td>Individual or Global</td></tr><tr><td>influence</td><td>Float</td><td>40</td><td>Influence reward gained on quest completion</td></tr><tr><td>duration</td><td>Integer</td><td>0</td><td>Maximum number of turns to complete the quest. If 0, there is no turn limit</td></tr><tr><td>minimumCivs</td><td>Integer</td><td>1</td><td>Minimum number of Civs needed to start the quest. It is meaningful only for type = Global</td></tr><tr><td>weightForCityStateType</td><td>Object</td><td>none</td><td>Relative weight multiplier to this quest for each <a href="#citystatetypesjson">city state type</a> or city state personality (Friendly, Neutral, Hostile, Irrational), <a href="#quest-weight">see below</a></td></tr></tbody></table><h3 id="quest-name" tabindex="-1">Quest name <a class="header-anchor" href="#quest-name" aria-label="Permalink to &quot;Quest name&quot;">​</a></h3><p>The name of the quest defines the criteria for the quest. If they are not defined in the predefined enum, they will have no behavior. In the description, square brackets <code>[]</code> in the description of the quest is replaced with extra information (except for <code>Invest</code>). The list of predefined quest names are as follows:</p><table tabindex="0"><thead><tr><th>Name</th><th>Criteria</th><th>Additional info</th></tr></thead><tbody><tr><td>Route</td><td>Connect the city state to the major civilization&#39;s capital using roads or railways</td><td></td></tr><tr><td>Clear Barbarian Camp</td><td>Destroy the target barbarian camp</td><td></td></tr><tr><td>Construct Wonder</td><td>Construct the target wonder</td><td>target <code>wonder</code></td></tr><tr><td>Connect Resource</td><td>Connect the target resource to the major civilization&#39;s trade network</td><td>target <code>tileResource</code></td></tr><tr><td>Acquire Great Person</td><td>Acquire the target great person</td><td>target <code>greatPerson</code></td></tr><tr><td>Conquer City State</td><td>Defeat the target city state</td><td>target <code>cityState</code></td></tr><tr><td>Find Player</td><td>Meet the target major civilization</td><td>target <code>civName</code></td></tr><tr><td>Find Natural Wonder</td><td>Find the target natural wonder</td><td>target <code>naturalWonder</code></td></tr><tr><td>Give Gold</td><td>Donate gold to the city state (amount does not matter)</td><td><code>civName</code> &quot;bully&quot; for city state</td></tr><tr><td>Pledge to Protect</td><td>Pledge to protect city state</td><td><code>civName</code> &quot;bully&quot; for city state</td></tr><tr><td>Contest Culture</td><td>Be the major civilization with the highest increase to culture during the duration</td><td>major civilization&#39;s <code>cultureGrowth</code></td></tr><tr><td>Contest Faith</td><td>Be the major civilization with the highest increase to faith during the duration</td><td>major civilization&#39;s <code>faithGrowth</code></td></tr><tr><td>Contest Technology</td><td>Be the major civilization with the most technologies researched during the duration</td><td>major civilization&#39;s <code>techsResearched</code></td></tr><tr><td>Invest</td><td>Donating gold yield extra Influence based on value provided</td><td><strong>IMPORTANT</strong>: value in square brackets is the extra influence in percent. i.e. [50] means 50%</td></tr><tr><td>Bully City State</td><td>Demand tribute from the target city state</td><td>target <code>city state</code></td></tr><tr><td>Denounce Civilization</td><td>Denounce the major civilization which &quot;bullied&quot; the city state</td><td><code>civName</code> &quot;bully&quot; for city state</td></tr><tr><td>Spread Religion</td><td>Spread major civilization&#39;s religion to the city state</td><td>major civilization&#39;s <code>religionName</code></td></tr></tbody></table><h3 id="quest-weight" tabindex="-1">Quest weight <a class="header-anchor" href="#quest-weight" aria-label="Permalink to &quot;Quest weight&quot;">​</a></h3><p>The &quot;weightForCityStateType&quot; object determines the quest&#39;s weight multiplier. When a city state initiates a quest, the initial weight is 1, and it is multiplied by values based on <a href="#citystatetypesjson">city state type</a> and personality (Friendly, Neutral, Hostile, Irrational). The AI then randomly selects a quest based on the final weighted values.</p><p>The object maps city state type and personality to the weight multipliers for the city state using strings to floats. If the preferred victory type is not found, the default multiplier is 1.</p><p>The code below is an example of a valid &quot;weightForCityStateType&quot; definition. In this case, a friendly militaristic city state will be 0.4 (0.2 × 2) times as likely to pick this quest than a quest with weight 1.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;weightForCityStateType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Hostile&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Friendly&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;Militaristic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="religions-json" tabindex="-1">Religions.json <a class="header-anchor" href="#religions-json" aria-label="Permalink to &quot;Religions.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/tree/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Religions.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This is just a list of Strings specifying all predefined religion names. Corresponding icons must exist, that&#39;s all to it. After all, they&#39;re just containers for <a href="#beliefsjson">beliefs</a>.</p><h2 id="specialists-json" tabindex="-1">Specialists.json <a class="header-anchor" href="#specialists-json" aria-label="Permalink to &quot;Specialists.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Specialists.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file should contain a list of all possible specialists that citizens can be assigned to.</p><p>Each specialist has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td><a href="./3-Map-related-JSON-files.html#general-stat"><code>&lt;stats&gt;</code></a></td><td>Float</td><td>0</td><td>Per-turn yield produced by the specialist</td></tr><tr><td>color</td><td><a href="./5-Miscellaneous-JSON-files.html#rgb-colors-list">List of 3× Integer</a></td><td>Required</td><td>Color of the image for this specialist</td></tr><tr><td>greatPersonPoints</td><td>Object</td><td>none</td><td>Great person points generated by this specialist per turn. Valid keys are the names of units (Great Scientist, Warrior, etc.), valid values are Integers</td></tr></tbody></table><h2 id="techs-json" tabindex="-1">Techs.json <a class="header-anchor" href="#techs-json" aria-label="Permalink to &quot;Techs.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Gods%20%26%20Kings/Techs.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file contains all the technologies that can be researched with science. It is organized into an outer list of &#39;columns&#39;, which in turn contains one or more tech each.</p><h3 id="column-structure" tabindex="-1">Column structure <a class="header-anchor" href="#column-structure" aria-label="Permalink to &quot;Column structure&quot;">​</a></h3><p>Each tech column has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>columnNumber</td><td>Integer</td><td>Required</td><td>Horizontal placement in the Tech Tree</td></tr><tr><td>era</td><td>String</td><td>Required</td><td>Determines era reached after researching any technologies in this column. Must be in <a href="./5-Miscellaneous-JSON-files.html#erasjson">Eras.json</a></td></tr><tr><td>techCost</td><td>Integer</td><td>0</td><td>Default cost of the techs in this column</td></tr><tr><td>buildingCost</td><td>Integer</td><td>Required</td><td>Default cost of buildings requiring this tech</td></tr><tr><td>wonderCost</td><td>Integer</td><td>Required</td><td>Default cost of wonders requiring this tech</td></tr><tr><td>techs</td><td>List</td><td>Required</td><td>List of <a href="#tech-structure">techs</a> - pay attention to the nesting of {} and []</td></tr></tbody></table><h4 id="tech-structure" tabindex="-1">Tech structure <a class="header-anchor" href="#tech-structure" aria-label="Permalink to &quot;Tech structure&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>row</td><td>Integer</td><td>0</td><td>Vertical placement in the Tech Tree, must be unique per column</td></tr><tr><td>cost</td><td>Integer</td><td><a href="#column-structure">Column techCost</a></td><td>The amount of science required to research this tech</td></tr><tr><td>prerequisites</td><td>List of Strings</td><td>empty</td><td>A list of the names of techs that are prerequisites of this tech. Only direct prerequisites are necessary</td></tr><tr><td>quote</td><td>String</td><td>none</td><td>A nice story presented to the player when they research this tech</td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> this technology grants</td></tr><tr><td>civilopediaText</td><td>List</td><td>empty</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table>`,83)])])}const g=e(d,[["render",s]]);export{p as __pageData,g as default};
